def test_encode_tree_ordinal_or_native() -> None:
    plan = encoding_plan("tree")
    assert "ordinal" in plan.options
    assert "native" in plan.options
    assert plan.default == "ordinal"
    assert plan.rule_id == "ENC-01"


def test_encode_high_cardinality_target_in_folds() -> None:
    plan = encoding_plan("linear", supervised=True, high_cardinality=True)
    assert "target" in plan.options
    assert plan.target_encode_in_folds is True
    assert plan.rule_id == "ENC-02"
    low = encoding_plan("linear", supervised=True, high_cardinality=False)
    assert "target" not in low.options


def test_encode_neural_embeddings() -> None:
    plan = encoding_plan("neural")
    assert "one_hot" in plan.options
    assert "embedding" in plan.options
    assert plan.default == "one_hot"
    assert plan.rule_id == "ENC-03"


def test_encode_clustering_with_categoricals() -> None:
    assert clustering_encoding(("region", "color")) == "kprototypes_or_gower"
    assert clustering_encoding(()) is None


def test_encoder_fit_within_fold() -> None:
    assert encoder_fits_inside_fold() is True


def test_scale_options_when_needed() -> None:
    plan = scaling_plan(True, family="linear")
    assert plan.needed is True
    assert plan.options == ("standard", "robust", "minmax")
    assert plan.default == "standard"
    assert plan.rule_id == "SCALE-01"


def test_scale_hidden_for_trees() -> None:
    plan = scaling_plan(False)
    assert plan.needed is False
    assert plan.options == ()
    assert plan.default is None
    assert plan.mandatory is False
    assert plan.rule_id == "SCALE-02"


def test_scale_mandatory_for_neural() -> None:
    plan = scaling_plan(True, family="neural")
    assert plan.mandatory is True
    assert plan.rule_id == "SCALE-03"


