def test_pca_suggested_for_highdim_clustering() -> None:
    assert pca_suggestion(40, "linear", task_type="clustering") == "pca_95pct"
    assert pca_suggestion(10, "linear", task_type="clustering") is None
    assert pca_suggestion(40, "linear", task_type="regression") is None


